        "живая струна": "live string",
        "глитч-перкуссия": "glitch percussion",
        "облако зёрен": "grain cloud",
        "бипы и капли": "bleeps, drips",
        "средний темп, простая мелодия": "medium tempo, simple melody",
        "живое рядом с синтетикой": "live next to synthetic",
